/*
 * dxm/test/dxm_host_callbacks.h - host callback-cell registry for tests
 *
 * Generated by: Claude Opus 5.5
 *
 * A dxm_$callback_t is the 4-byte code address the image stores in a queue
 * entry (dxm/dxm.h, source-wy9y).  A 64-bit host cannot put a function
 * address in four bytes, so on the host the cell holds a 1-based handle into
 * this table and dxm_$callback_fn() maps it back.  This is test support, not
 * kernel data: it moved out of dxm/dxm_data.c (source-702z), which may not
 * carry host-only definitions.  A test that runs the queue with real cells
 * includes it once; other tests define the two hooks themselves.
 */

#ifndef DXM_TEST_DXM_HOST_CALLBACKS_H
#define DXM_TEST_DXM_HOST_CALLBACKS_H

#include "dxm/dxm.h"

static dxm_$callback_fn_t dxm_$host_callbacks[DXM_HOST_CALLBACK_MAX];
static uint32_t dxm_$host_callback_count;

dxm_$callback_t dxm_$callback_cell(dxm_$callback_fn_t fn)
{
    uint32_t i;

    for (i = 0; i < dxm_$host_callback_count; i++) {
        if (dxm_$host_callbacks[i] == fn) {
            return (dxm_$callback_t)(i + 1);
        }
    }
    if (dxm_$host_callback_count >= DXM_HOST_CALLBACK_MAX) {
        return 0;
    }
    dxm_$host_callbacks[dxm_$host_callback_count] = fn;
    dxm_$host_callback_count++;
    return (dxm_$callback_t)dxm_$host_callback_count;
}

dxm_$callback_fn_t dxm_$callback_fn(dxm_$callback_t cell)
{
    if (cell == 0 || cell > dxm_$host_callback_count) {
        return NULL;
    }
    return dxm_$host_callbacks[cell - 1];
}

#endif /* DXM_TEST_DXM_HOST_CALLBACKS_H */
